import com.google.gson.*;
import net.runelite.api.Client;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarPlayerID;
/** Local game-cache metadata only; no dependency on another hub plugin. */
final class GearContainers {
 static final int[] BOLT_TYPES={VarbitID.XBOWS_POUCH_SLOT1,VarbitID.XBOWS_POUCH_SLOT2,VarbitID.XBOWS_POUCH_SLOT3,VarbitID.XBOWS_POUCH_SLOT4};
 static final int[] BOLT_AMOUNTS={VarbitID.XBOWS_POUCH_NUM1,VarbitID.XBOWS_POUCH_NUM2,VarbitID.XBOWS_POUCH_NUM3,VarbitID.XBOWS_POUCH_NUM4};
 private static final int[] BOLTS={-1,ItemID.BOLT,ItemID.XBOWS_CROSSBOW_BOLTS_BLURITE,ItemID.XBOWS_CROSSBOW_BOLTS_IRON,ItemID.XBOWS_CROSSBOW_BOLTS_STEEL,ItemID.XBOWS_CROSSBOW_BOLTS_MITHRIL,ItemID.XBOWS_CROSSBOW_BOLTS_ADAMANTITE,ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE,ItemID.XBOWS_CROSSBOW_BOLTS_SILVER,ItemID.POISON_BOLT,ItemID.XBOWS_CROSSBOW_BOLTS_BLURITE_POISONED,ItemID.XBOWS_CROSSBOW_BOLTS_IRON_POISONED,ItemID.XBOWS_CROSSBOW_BOLTS_STEEL_POISONED,ItemID.XBOWS_CROSSBOW_BOLTS_MITHRIL_POISONED,ItemID.XBOWS_CROSSBOW_BOLTS_ADAMANTITE_POISONED,ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE_POISONED,ItemID.XBOWS_CROSSBOW_BOLTS_SILVER_POISONED,ItemID.POISON_BOLT_,ItemID.XBOWS_CROSSBOW_BOLTS_BLURITE_POISONED_,ItemID.XBOWS_CROSSBOW_BOLTS_IRON_POISONED_,ItemID.XBOWS_CROSSBOW_BOLTS_STEEL_POISONED_,ItemID.XBOWS_CROSSBOW_BOLTS_MITHRIL_POISONED_,ItemID.XBOWS_CROSSBOW_BOLTS_ADAMANTITE_POISONED_,ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE_POISONED_,ItemID.XBOWS_CROSSBOW_BOLTS_SILVER_POISONED_,ItemID.POISON_BOLT__,ItemID.XBOWS_CROSSBOW_BOLTS_BLURITE_POISONED__,ItemID.XBOWS_CROSSBOW_BOLTS_IRON_POISONED__,ItemID.XBOWS_CROSSBOW_BOLTS_STEEL_POISONED__,ItemID.XBOWS_CROSSBOW_BOLTS_MITHRIL_POISONED__,ItemID.XBOWS_CROSSBOW_BOLTS_ADAMANTITE_POISONED__,ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE_POISONED__,ItemID.XBOWS_CROSSBOW_BOLTS_SILVER_POISONED__,ItemID.OPAL_BOLT,ItemID.XBOWS_CROSSBOW_BOLTS_BLURITE_TIPPED_JADE,ItemID.PEARL_BOLT,ItemID.XBOWS_CROSSBOW_BOLTS_STEEL_TIPPED_REDTOPAZ,ItemID.XBOWS_CROSSBOW_BOLTS_MITHRIL_TIPPED_SAPPHIRE,ItemID.XBOWS_CROSSBOW_BOLTS_MITHRIL_TIPPED_EMERALD,ItemID.XBOWS_CROSSBOW_BOLTS_ADAMANTITE_TIPPED_RUBY,ItemID.XBOWS_CROSSBOW_BOLTS_ADAMANTITE_TIPPED_DIAMOND,ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE_TIPPED_DRAGONSTONE,ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE_TIPPED_ONYX,ItemID.XBOWS_CROSSBOW_BOLTS_BRONZE_TIPPED_OPAL_ENCHANTED,ItemID.XBOWS_CROSSBOW_BOLTS_BLURITE_TIPPED_JADE_ENCHANTED,ItemID.XBOWS_CROSSBOW_BOLTS_IRON_TIPPED_PEARL_ENCHANTED,ItemID.XBOWS_CROSSBOW_BOLTS_STEEL_TIPPED_REDTOPAZ_ENCHANTED,ItemID.XBOWS_CROSSBOW_BOLTS_MITHRIL_TIPPED_SAPPHIRE_ENCHANTED,ItemID.XBOWS_CROSSBOW_BOLTS_MITHRIL_TIPPED_EMERALD_ENCHANTED,ItemID.XBOWS_CROSSBOW_BOLTS_ADAMANTITE_TIPPED_RUBY_ENCHANTED,ItemID.XBOWS_CROSSBOW_BOLTS_ADAMANTITE_TIPPED_DIAMOND_ENCHANTED,ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE_TIPPED_DRAGONSTONE_ENCHANTED,ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE_TIPPED_ONYX_ENCHANTED,ItemID.XBOWS_GRAPPLE_TIP_BOLT_MITHRIL_ROPE,ItemID.BARBED_BOLT,ItemID.DTTD_BONE_CROSSBOW_BOLT,ItemID.SLAYER_BROAD_BOLT,ItemID.SLAYER_BROAD_BOLT_AMETHYST,ItemID.DRAGON_BOLTS,ItemID.DRAGON_BOLTS_P,ItemID.DRAGON_BOLTS_P_,ItemID.DRAGON_BOLTS_P__,ItemID.DRAGON_BOLTS_UNENCHANTED_OPAL,ItemID.DRAGON_BOLTS_UNENCHANTED_JADE,ItemID.DRAGON_BOLTS_UNENCHANTED_PEARL,ItemID.DRAGON_BOLTS_UNENCHANTED_TOPAZ,ItemID.DRAGON_BOLTS_UNENCHANTED_SAPPHIRE,ItemID.DRAGON_BOLTS_UNENCHANTED_EMERALD,ItemID.DRAGON_BOLTS_UNENCHANTED_RUBY,ItemID.DRAGON_BOLTS_UNENCHANTED_DIAMOND,ItemID.DRAGON_BOLTS_UNENCHANTED_DRAGONSTONE,ItemID.DRAGON_BOLTS_UNENCHANTED_ONYX,ItemID.DRAGON_BOLTS_ENCHANTED_OPAL,ItemID.DRAGON_BOLTS_ENCHANTED_JADE,ItemID.DRAGON_BOLTS_ENCHANTED_PEARL,ItemID.DRAGON_BOLTS_ENCHANTED_TOPAZ,ItemID.DRAGON_BOLTS_ENCHANTED_SAPPHIRE,ItemID.DRAGON_BOLTS_ENCHANTED_EMERALD,ItemID.DRAGON_BOLTS_ENCHANTED_RUBY,ItemID.DRAGON_BOLTS_ENCHANTED_DIAMOND,ItemID.DRAGON_BOLTS_ENCHANTED_DRAGONSTONE,ItemID.DRAGON_BOLTS_ENCHANTED_ONYX,ItemID.BARROWS_KARIL_AMMO};
 static boolean isBoltVarbit(int bit){for(int id:BOLT_TYPES)if(id==bit)return true;for(int id:BOLT_AMOUNTS)if(id==bit)return true;return false;}
 static int[] trackedVarbits(){int[] core={VarbitID.SPELLBOOK,VarbitID.COMBAT_WEAPON_CATEGORY,VarbitID.AUTOCAST_DEFMODE,VarbitID.RUNE_POUCH_TYPE_1,VarbitID.RUNE_POUCH_TYPE_2,VarbitID.RUNE_POUCH_TYPE_3,VarbitID.RUNE_POUCH_TYPE_4,VarbitID.RUNE_POUCH_QUANTITY_1,VarbitID.RUNE_POUCH_QUANTITY_2,VarbitID.RUNE_POUCH_QUANTITY_3,VarbitID.RUNE_POUCH_QUANTITY_4};int[] all=java.util.Arrays.copyOf(core,core.length+8);System.arraycopy(BOLT_TYPES,0,all,core.length,4);System.arraycopy(BOLT_AMOUNTS,0,all,core.length+4,4);return all;}
 static int boltId(int type){return type>0&&type<BOLTS.length?BOLTS[type]:-1;}
 static void capture(Client client,JsonObject setup){
  boolean pouch=false;for(JsonElement e:setup.getAsJsonArray("inv"))if(SetupCodec.id(e)==ItemID.XBOWS_BOLT_POUCH)pouch=true;
  if(pouch){JsonArray contents=SetupCodec.empty(4);for(int i=0;i<4;i++){int id=boltId(client.getVarbitValue(BOLT_TYPES[i])),amount=client.getVarbitValue(BOLT_AMOUNTS[i]);if(id>0&&amount>0)contents.set(i,SetupCodec.item(id,amount));}setup.add("bp",contents);}
  String option=attackOption(client);if(!option.isEmpty())setup.addProperty("ao",option);
 }
 static String attackOption(Client client){
  int mode=client.getVarpValue(VarPlayerID.COM_MODE),category=client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY);
  if(mode==4)return client.getVarbitValue(VarbitID.AUTOCAST_DEFMODE)==1?"D. Cast":"Cast";
  // Cache DBTable 78 maps weapon categories to combat modes; no gameval constant exists.
  try{for(int row:client.getDBTableRows(78)){Object[] kind=client.getDBTableField(row,0,0);if(kind.length==0||!kind[0].equals(category))continue;Object[] modes=client.getDBTableField(row,1,0),names=client.getDBTableField(row,1,1);for(int i=0;i<Math.min(modes.length,names.length);i++)if(modes[i].equals(mode))return String.valueOf(names[i]);}}catch(RuntimeException ex){return "";}return "";
 }
}

